const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\([^)]*\)/g,' ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
const aliases=[['aji lamu pantomime','aji lhamu','aji lamu'],['pangong tso','pangong lake'],['churches and convents of old goa','churches and convents of goa'],['nati','nati dance'],['fugdi','fugdi dance'],['rouff','rouf','rouf dance'],['chhau dance of purulia','chhau of purulia'],['oggu katha','oggukatha'],['channapatna wooden toys','channapatna toys and dolls'],['kondapalli toys','kondapalli bommallu'],['sohrai painting','sohrai khovar painting'],['chamba rumal embroidery','chamba rumal'],['phulkari embroidery','phulkari'],['sao joao festival','sao joao'],['dohneiiong','doh sniang nei iong']];
const canon=s=>{const n=norm(s);for(const g of aliases)if(g.some(x=>norm(x)===n))return norm(g[0]);return n;};
const same=(a,b)=>canon(a)===canon(b);
const verField={classical:'classical',folk:'traditions',festivals:'festivals',foods:'foods',wildlife:'wildlife',famous:'famous'};
const reviewField={classical:'classical',folk:'folk',festivals:'festivals',foods:'foods',wildlife:'wildlife',famous:'famous'};
const verifiedAdds=window.BME_M102_VERIFIED_ADDITIONS||[];
Object.keys(window.CONTENT||{}).forEach(id=>{const c=window.CONTENT[id];if(!c.dk)c.dk={folk:[],festivals:[],foods:[],wildlife:[],famous:[]};
  // Verified additions supersede matching entries in the old Review lists, but only in the corresponding category.
  for(const rf of ['classical','folk','festivals','foods','wildlife','famous']){const vf=verField[rf];const existing=(c[vf]||[]).map(x=>x.en);
    const accepted=verifiedAdds.filter(e=>e.stateId===id && e.field===vf).map(e=>e.item.en);
    c.dk[rf]=(c.dk[rf]||[]).filter(x=>!existing.some(v=>same(v,x.en))&&!accepted.some(v=>same(v,x.en)));
  }
  const animals=verifiedAdds.filter(e=>e.stateId===id&&e.category==='stateAnimal').map(e=>e.item.en);
  c.dk.animalCandidate=(c.dk.animalCandidate||[]).filter(x=>!animals.some(v=>same(v,x.en)));
});
EXTRA.forEach(e=>{const c=window.CONTENT&&window.CONTENT[e.stateId];if(!c)return;if(!c.dk)c.dk={folk:[],festivals:[],foods:[],wildlife:[],famous:[]};
 Object.entries(e.categories).forEach(([cat,items])=>{if(!Array.isArray(c.dk[cat]))c.dk[cat]=[];const verifiedField=verField[cat];const vf=verifiedField?(c[verifiedField]||[]):[];items.forEach(it=>{if(cat!=='animalCandidate'&&vf.some(v=>same(v.en,it.en)))return;if(c.dk[cat].some(v=>same(v.en,it.en)))return;c.dk[cat].push(it);});});
});
window.BME_M102_REVIEW_ADDITIONS=EXTRA;
